#include <map>
#include <string>

int main() {
    std::map<std::string, float> coll;

    // 1. Explicit value_type (always safe)
    coll.insert(std::map<std::string, float>::value_type("v_type", 1.1));

    // 2. Using make_pair (most convenient, relies on member template)
    coll.insert(std::make_pair("make_pair", 2.2));

    // 3. Using std::pair (relies on implicit conversion via template)
    coll.insert(std::pair<std::string, float>("pair_non_const", 3.3));

    // 4. Explicitly providing const key (avoids implicit conversion)
    coll.insert(std::pair<const std::string, float>("pair_const", 4.4));
}
